class Solution {
public:
    vector<long long> getDistances(vector<int>& arr) {
        int n = arr.size();
        unordered_map<int, vector<int>> groups;
        for (int i = 0; i < n; i++) {
            groups[arr[i]].push_back(i);
        }
        vector<long long> result(n, 0);
        for (auto& [val, indices] : groups) {
            (void)val;
            int m = indices.size();
            vector<long long> prefix(m + 1, 0);
            for (int i = 0; i < m; i++) {
                prefix[i + 1] = prefix[i] + indices[i];
            }
            long long total = prefix[m];
            for (int k = 0; k < m; k++) {
                long long left = (long long)k * indices[k] - prefix[k];
                long long right = (total - prefix[k + 1]) - (long long)(m - 1 - k) * indices[k];
                result[indices[k]] = left + right;
            }
        }
        return result;
    }
};
